with authored(item_code,definition_code,display_order,skill_code,prompt,answer_config,solution,difficulty,reasoning_classification,cognitive_level) as (
values
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.1', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 1, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √49?', '{"type":"multiple_choice","options":{"A":"It is the negative integer −7.","B":"7 is a natural number, an integer and a rational number.","C":"It is irrational because it is written with a root sign.","D":"It is not real because square roots are not numbers."},"correct_option":"B","distractor_explanations":{"A":"√ denotes the principal, non-negative square root.","C":"The radicand is a perfect square, so its square root is an integer.","D":"The square root of a positive number is real."}}'::jsonb, '√49 = 7. Every natural number is also an integer and rational.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.2', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 2, 'G9-NUM-REAL-IRRATIONAL', 'Which number is irrational in this number set 1?', '{"type":"multiple_choice","options":{"A":"√18","B":"√49","C":"0.125","D":"−3/8"},"correct_option":"A","distractor_explanations":{"B":"√49 is an integer and is therefore rational.","C":"A terminating decimal is rational.","D":"A ratio of integers with a non-zero denominator is rational."}}'::jsonb, '18 is not a perfect square, so √18 cannot be written as a ratio of integers. The other three numbers are rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.3', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 3, 'G9-NUM-WHOLE-HCF-LCM', 'What is the prime factorisation of 60?', '{"type":"multiple_choice","options":{"A":"2^1 × 3 × 5","B":"2^2 × 3² × 5","C":"2^3 × 3 × 5","D":"2^2 × 3 × 5"},"correct_option":"D","distractor_explanations":{"A":"This omits one factor of 2.","B":"This introduces an extra factor of 3.","C":"This introduces an extra factor of 2."}}'::jsonb, '60 = 4 × 15 = 2^2 × 3 × 5.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.4', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 4, 'G9-NUM-WHOLE-HCF-LCM', 'Determine the HCF of 12 and 18.', '{"type":"multiple_choice","options":{"A":"12","B":"18","C":"6","D":"2"},"correct_option":"C","distractor_explanations":{"A":"This is one of the numbers, not a factor of 18.","B":"This is one of the numbers, not a factor of 12.","D":"This is common, but not the highest common factor."}}'::jsonb, '12 = 2 × 3 × 2 and 18 = 3² × 2. The common factors give 3 × 2 = 6.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.5', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 5, 'G9-NUM-WHOLE-HCF-LCM', 'Two bells ring every 8 and 12 minutes. After how many minutes will they next ring together?', '{"type":"multiple_choice","options":{"A":"48","B":"24","C":"4","D":"20"},"correct_option":"B","distractor_explanations":{"A":"This doubles the LCM unnecessarily.","C":"This is the HCF, not the first common multiple.","D":"This is not divisible by both intervals."}}'::jsonb, 'LCM(8, 12) = LCM(2² × 2, 2 × 3 × 2) = 2² × 3 × 2 = 24.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.6', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 6, 'G9-NUM-RATIO-RATE', 'A fruit drink uses 4:3 cups of juice to water. How many cups of water are needed for 8 cups of juice?', '{"type":"multiple_choice","options":{"A":"6","B":"3","C":"8","D":"12"},"correct_option":"A","distractor_explanations":{"B":"This keeps the original water amount instead of scaling it.","C":"This repeats the juice amount as water.","D":"This multiplies the water by the juice amount rather than by the scale factor."}}'::jsonb, 'The juice amount doubles from 4 to 8. Water must also double: 3 × 2 = 6 cups.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.7', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 7, 'G9-NUM-RATIO-RATE', 'A cyclist travels 30 km in 2 hours at a constant speed. What is the unit rate?', '{"type":"multiple_choice","options":{"A":"32 km/h","B":"28 km/h","C":"60 km/h","D":"15 km/h"},"correct_option":"D","distractor_explanations":{"A":"This adds distance and time instead of dividing.","B":"This subtracts rather than finding a unit rate.","C":"This multiplies distance by time instead of dividing."}}'::jsonb, 'Speed = distance ÷ time = 30 ÷ 2 = 15 km/h.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.8', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 8, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Five identical notebooks cost R45. At the same price per notebook, what do eight notebooks cost?', '{"type":"multiple_choice","options":{"A":"R360","B":"R9","C":"R72","D":"R53"},"correct_option":"C","distractor_explanations":{"A":"This multiplies the total for five notebooks by eight.","B":"This is the unit price, not the price of eight notebooks.","D":"This adds the number of notebooks to the price."}}'::jsonb, 'One notebook costs R45 ÷ 5 = R9. Eight cost 8 × R9 = R72.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.9', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 9, 'G9-NUM-RATIO-RATE', 'A paint mix has red : white = 4 : 3. If the red paint is increased to 8 cups, how much white paint is needed to keep the same mix?', '{"type":"multiple_choice","options":{"A":"12 cups","B":"6 cups","C":"3 cups","D":"8 cups"},"correct_option":"B","distractor_explanations":{"A":"This multiplies by the original red amount rather than the scale factor 2.","C":"This leaves the white amount unchanged while the red amount doubles.","D":"This copies the red amount instead of scaling the white part."}}'::jsonb, 'The red amount doubles from 4 to 8, so the white amount must also double: 3 × 2 = 6 cups.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.10', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 10, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √484?', '{"type":"multiple_choice","options":{"A":"√484 is irrational because it has a root sign.","B":"√484 = −22.","C":"√484 is not real.","D":"√484 = 22, so it is rational."},"correct_option":"D","distractor_explanations":{"A":"The radicand is a perfect square, so its principal root is an integer.","B":"The square-root symbol denotes the principal non-negative root.","C":"The square root of a positive perfect square is real."}}'::jsonb, 'Because 22 × 22 = 484, √484 = 22. Every integer is rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.11', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 11, 'G9-NUM-REAL-IRRATIONAL', 'Which value is √(1/16)?', '{"type":"multiple_choice","options":{"A":"4","B":"−1/4","C":"1/4","D":"1/16"},"correct_option":"C","distractor_explanations":{"A":"This is the denominator rather than the positive fractional root.","B":"The principal square root is non-negative.","D":"This repeats the radicand rather than taking its square root."}}'::jsonb, '(1/4)² = 1/16, so √(1/16) = 1/4. This is rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.TOPIC-BASELINE.12', 'G9-T1-WHOLE-MASTERY-TOPIC-BASELINE', 12, 'G9-NUM-FINANCIAL-APPLICATIONS', 'R1200 is invested at 10% compound interest per year. What is the balance after two years?', '{"type":"multiple_choice","options":{"A":"R1462.00","B":"R1452.00","C":"R1440.00","D":"R1320.00"},"correct_option":"B","distractor_explanations":{"A":"This adds an extra R10 after compounding.","C":"This adds simple interest for two years.","D":"This stops after one year."}}'::jsonb, 'After year 1: R1200 × 1.10 = R1320.00. After year 2: R1320.00 × 1.10 = R1452.00.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE.1', 'G9-T1-WHOLE-MASTERY-ENDLINE', 1, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √64?', '{"type":"multiple_choice","options":{"A":"It is irrational because it is written with a root sign.","B":"It is not real because square roots are not numbers.","C":"It is the negative integer −8.","D":"8 is a natural number, an integer and a rational number."},"correct_option":"D","distractor_explanations":{"A":"The radicand is a perfect square, so its square root is an integer.","B":"The square root of a positive number is real.","C":"√ denotes the principal, non-negative square root."}}'::jsonb, '√64 = 8. Every natural number is also an integer and rational.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE.2', 'G9-T1-WHOLE-MASTERY-ENDLINE', 2, 'G9-NUM-REAL-IRRATIONAL', 'Which number is irrational in this number set 2?', '{"type":"multiple_choice","options":{"A":"0.125","B":"−3/8","C":"√12","D":"√64"},"correct_option":"C","distractor_explanations":{"A":"A terminating decimal is rational.","B":"A ratio of integers with a non-zero denominator is rational.","D":"√64 is an integer and is therefore rational."}}'::jsonb, '12 is not a perfect square, so √12 cannot be written as a ratio of integers. The other three numbers are rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE.3', 'G9-T1-WHOLE-MASTERY-ENDLINE', 3, 'G9-NUM-WHOLE-HCF-LCM', 'What is the prime factorisation of 120?', '{"type":"multiple_choice","options":{"A":"2^4 × 3 × 5","B":"2^3 × 3 × 5","C":"2^2 × 3 × 5","D":"2^3 × 3² × 5"},"correct_option":"B","distractor_explanations":{"A":"This introduces an extra factor of 2.","C":"This omits one factor of 2.","D":"This introduces an extra factor of 3."}}'::jsonb, '120 = 8 × 15 = 2^3 × 3 × 5.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE.4', 'G9-T1-WHOLE-MASTERY-ENDLINE', 4, 'G9-NUM-WHOLE-HCF-LCM', 'Determine the HCF of 18 and 27.', '{"type":"multiple_choice","options":{"A":"9","B":"3","C":"18","D":"27"},"correct_option":"A","distractor_explanations":{"B":"This is common, but not the highest common factor.","C":"This is one of the numbers, not a factor of 27.","D":"This is one of the numbers, not a factor of 18."}}'::jsonb, '18 = 2 × 3 × 3 and 27 = 3² × 3. The common factors give 3 × 3 = 9.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE.5', 'G9-T1-WHOLE-MASTERY-ENDLINE', 5, 'G9-NUM-WHOLE-HCF-LCM', 'Two bells ring every 12 and 18 minutes. After how many minutes will they next ring together?', '{"type":"multiple_choice","options":{"A":"6","B":"30","C":"72","D":"36"},"correct_option":"D","distractor_explanations":{"A":"This is the HCF, not the first common multiple.","B":"This is not divisible by both intervals.","C":"This doubles the LCM unnecessarily."}}'::jsonb, 'LCM(12, 18) = LCM(2² × 3, 2 × 3 × 3) = 2² × 3 × 3 = 36.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE.6', 'G9-T1-WHOLE-MASTERY-ENDLINE', 6, 'G9-NUM-RATIO-RATE', 'A fruit drink uses 5:3 cups of juice to water. How many cups of water are needed for 10 cups of juice?', '{"type":"multiple_choice","options":{"A":"10","B":"15","C":"6","D":"3"},"correct_option":"C","distractor_explanations":{"A":"This repeats the juice amount as water.","B":"This multiplies the water by the juice amount rather than by the scale factor.","D":"This keeps the original water amount instead of scaling it."}}'::jsonb, 'The juice amount doubles from 5 to 10. Water must also double: 3 × 2 = 6 cups.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE.7', 'G9-T1-WHOLE-MASTERY-ENDLINE', 7, 'G9-NUM-RATIO-RATE', 'A cyclist travels 45 km in 3 hours at a constant speed. What is the unit rate?', '{"type":"multiple_choice","options":{"A":"135 km/h","B":"15 km/h","C":"48 km/h","D":"42 km/h"},"correct_option":"B","distractor_explanations":{"A":"This multiplies distance by time instead of dividing.","C":"This adds distance and time instead of dividing.","D":"This subtracts rather than finding a unit rate."}}'::jsonb, 'Speed = distance ÷ time = 45 ÷ 3 = 15 km/h.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE.8', 'G9-T1-WHOLE-MASTERY-ENDLINE', 8, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Five identical notebooks cost R50. At the same price per notebook, what do eight notebooks cost?', '{"type":"multiple_choice","options":{"A":"R80","B":"R58","C":"R400","D":"R10"},"correct_option":"A","distractor_explanations":{"B":"This adds the number of notebooks to the price.","C":"This multiplies the total for five notebooks by eight.","D":"This is the unit price, not the price of eight notebooks."}}'::jsonb, 'One notebook costs R50 ÷ 5 = R10. Eight cost 8 × R10 = R80.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE.9', 'G9-T1-WHOLE-MASTERY-ENDLINE', 9, 'G9-NUM-RATIO-RATE', 'A paint mix has red : white = 5 : 3. If the red paint is increased to 10 cups, how much white paint is needed to keep the same mix?', '{"type":"multiple_choice","options":{"A":"3 cups","B":"10 cups","C":"15 cups","D":"6 cups"},"correct_option":"D","distractor_explanations":{"A":"This leaves the white amount unchanged while the red amount doubles.","B":"This copies the red amount instead of scaling the white part.","C":"This multiplies by the original red amount rather than the scale factor 2."}}'::jsonb, 'The red amount doubles from 5 to 10, so the white amount must also double: 3 × 2 = 6 cups.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE.10', 'G9-T1-WHOLE-MASTERY-ENDLINE', 10, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √529?', '{"type":"multiple_choice","options":{"A":"√529 is not real.","B":"√529 = 23, so it is rational.","C":"√529 is irrational because it has a root sign.","D":"√529 = −23."},"correct_option":"B","distractor_explanations":{"A":"The square root of a positive perfect square is real.","C":"The radicand is a perfect square, so its principal root is an integer.","D":"The square-root symbol denotes the principal non-negative root."}}'::jsonb, 'Because 23 × 23 = 529, √529 = 23. Every integer is rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE.11', 'G9-T1-WHOLE-MASTERY-ENDLINE', 11, 'G9-NUM-REAL-IRRATIONAL', 'Which value is √(1/25)?', '{"type":"multiple_choice","options":{"A":"1/5","B":"1/25","C":"5","D":"−1/5"},"correct_option":"A","distractor_explanations":{"B":"This repeats the radicand rather than taking its square root.","C":"This is the denominator rather than the positive fractional root.","D":"The principal square root is non-negative."}}'::jsonb, '(1/5)² = 1/25, so √(1/25) = 1/5. This is rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE.12', 'G9-T1-WHOLE-MASTERY-ENDLINE', 12, 'G9-NUM-FINANCIAL-APPLICATIONS', 'R1300 is invested at 10% compound interest per year. What is the balance after two years?', '{"type":"multiple_choice","options":{"A":"R1560.00","B":"R1430.00","C":"R1583.00","D":"R1573.00"},"correct_option":"D","distractor_explanations":{"A":"This adds simple interest for two years.","B":"This stops after one year.","C":"This adds an extra R10 after compounding."}}'::jsonb, 'After year 1: R1300 × 1.10 = R1430.00. After year 2: R1430.00 × 1.10 = R1573.00.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE.13', 'G9-T1-WHOLE-MASTERY-ENDLINE', 13, 'G9-NUM-WHOLE-HCF-LCM', 'A learner says the HCF of 24 and 30 is their product. Which correction is valid?', '{"type":"multiple_choice","options":{"A":"HCF is always the smaller of the two numbers.","B":"HCF means the least common multiple of the two numbers.","C":"HCF means the greatest number that divides both; 6 divides both 24 and 30.","D":"HCF means multiply the two numbers and then choose a factor."},"correct_option":"C","distractor_explanations":{"A":"The smaller number need not divide the larger one.","B":"LCM and HCF are different concepts.","D":"The product is not the definition of HCF."}}'::jsonb, '24 = 6 × 4 and 30 = 6 × 5. The common greatest factor is 6.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE.14', 'G9-T1-WHOLE-MASTERY-ENDLINE', 14, 'G9-NUM-RATIO-RATE', 'Map set 2 has scale 1 cm : 6 km. Which calculation models 8.5 cm on the map?', '{"type":"multiple_choice","options":{"A":"8.5 km","B":"8.5 × 6 = 51 km","C":"8.5 ÷ 6 km","D":"8.5 + 6 km"},"correct_option":"B","distractor_explanations":{"A":"This ignores that 1 cm represents 6 km.","C":"Dividing reverses the scale relationship.","D":"A scale is multiplicative, not additive."}}'::jsonb, 'Each centimetre represents 6 km. Therefore 8.5 cm represents 8.5 × 6 = 51 km.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE.15', 'G9-T1-WHOLE-MASTERY-ENDLINE', 15, 'G9-NUM-FINANCIAL-APPLICATIONS', 'Why is compound interest on R1100 at 8% for two years greater than simple interest at the same rate?', '{"type":"multiple_choice","options":{"A":"The second year’s interest is calculated on R1188.00, not on R1100.","B":"The percentage becomes 16% in the second year.","C":"Interest is subtracted in the first year and added in the second.","D":"The principal is divided by the rate each year."},"correct_option":"A","distractor_explanations":{"B":"The annual rate remains unchanged.","C":"Both years add interest for a positive investment.","D":"The rate is applied to the growing balance."}}'::jsonb, 'After year 1 the balance is R1100 × 1.08 = R1188.00. Year 2 interest is calculated from that balance.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE.16', 'G9-T1-WHOLE-MASTERY-ENDLINE', 16, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Which situation in set 2 is inverse proportion?', '{"type":"multiple_choice","options":{"A":"At a fixed unit price, buying more pens increases the total cost.","B":"A recipe doubles every ingredient when the number of portions doubles.","C":"A taxi fare rises when more kilometres are travelled at a fixed rate.","D":"For a fixed journey, a faster constant speed gives a shorter travel time."},"correct_option":"D","distractor_explanations":{"A":"Both quantities increase together, so this is direct proportion.","B":"Both quantities increase together, so this is direct proportion.","C":"Distance and fare increase together, so this is direct proportion."}}'::jsonb, 'For a fixed total task, rate × time is constant. Increasing the rate or workers therefore decreases the time.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.1', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 1, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √81?', '{"type":"multiple_choice","options":{"A":"It is the negative integer −9.","B":"9 is a natural number, an integer and a rational number.","C":"It is irrational because it is written with a root sign.","D":"It is not real because square roots are not numbers."},"correct_option":"B","distractor_explanations":{"A":"√ denotes the principal, non-negative square root.","C":"The radicand is a perfect square, so its square root is an integer.","D":"The square root of a positive number is real."}}'::jsonb, '√81 = 9. Every natural number is also an integer and rational.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.2', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 2, 'G9-NUM-REAL-IRRATIONAL', 'Which number is irrational in this number set 3?', '{"type":"multiple_choice","options":{"A":"√27","B":"√81","C":"0.125","D":"−3/8"},"correct_option":"A","distractor_explanations":{"B":"√81 is an integer and is therefore rational.","C":"A terminating decimal is rational.","D":"A ratio of integers with a non-zero denominator is rational."}}'::jsonb, '27 is not a perfect square, so √27 cannot be written as a ratio of integers. The other three numbers are rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.3', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 3, 'G9-NUM-WHOLE-HCF-LCM', 'What is the prime factorisation of 240?', '{"type":"multiple_choice","options":{"A":"2^3 × 3 × 5","B":"2^4 × 3² × 5","C":"2^5 × 3 × 5","D":"2^4 × 3 × 5"},"correct_option":"D","distractor_explanations":{"A":"This omits one factor of 2.","B":"This introduces an extra factor of 3.","C":"This introduces an extra factor of 2."}}'::jsonb, '240 = 16 × 15 = 2^4 × 3 × 5.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.4', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 4, 'G9-NUM-WHOLE-HCF-LCM', 'Determine the HCF of 24 and 36.', '{"type":"multiple_choice","options":{"A":"24","B":"36","C":"12","D":"4"},"correct_option":"C","distractor_explanations":{"A":"This is one of the numbers, not a factor of 36.","B":"This is one of the numbers, not a factor of 24.","D":"This is common, but not the highest common factor."}}'::jsonb, '24 = 2 × 3 × 4 and 36 = 3² × 4. The common factors give 3 × 4 = 12.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.5', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 5, 'G9-NUM-WHOLE-HCF-LCM', 'Two bells ring every 16 and 24 minutes. After how many minutes will they next ring together?', '{"type":"multiple_choice","options":{"A":"96","B":"48","C":"8","D":"40"},"correct_option":"B","distractor_explanations":{"A":"This doubles the LCM unnecessarily.","C":"This is the HCF, not the first common multiple.","D":"This is not divisible by both intervals."}}'::jsonb, 'LCM(16, 24) = LCM(2² × 4, 2 × 3 × 4) = 2² × 3 × 4 = 48.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.6', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 6, 'G9-NUM-RATIO-RATE', 'A fruit drink uses 6:3 cups of juice to water. How many cups of water are needed for 12 cups of juice?', '{"type":"multiple_choice","options":{"A":"6","B":"3","C":"12","D":"18"},"correct_option":"A","distractor_explanations":{"B":"This keeps the original water amount instead of scaling it.","C":"This repeats the juice amount as water.","D":"This multiplies the water by the juice amount rather than by the scale factor."}}'::jsonb, 'The juice amount doubles from 6 to 12. Water must also double: 3 × 2 = 6 cups.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.7', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 7, 'G9-NUM-RATIO-RATE', 'A cyclist travels 60 km in 4 hours at a constant speed. What is the unit rate?', '{"type":"multiple_choice","options":{"A":"64 km/h","B":"56 km/h","C":"240 km/h","D":"15 km/h"},"correct_option":"D","distractor_explanations":{"A":"This adds distance and time instead of dividing.","B":"This subtracts rather than finding a unit rate.","C":"This multiplies distance by time instead of dividing."}}'::jsonb, 'Speed = distance ÷ time = 60 ÷ 4 = 15 km/h.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.8', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 8, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Five identical notebooks cost R55. At the same price per notebook, what do eight notebooks cost?', '{"type":"multiple_choice","options":{"A":"R440","B":"R11","C":"R88","D":"R63"},"correct_option":"C","distractor_explanations":{"A":"This multiplies the total for five notebooks by eight.","B":"This is the unit price, not the price of eight notebooks.","D":"This adds the number of notebooks to the price."}}'::jsonb, 'One notebook costs R55 ÷ 5 = R11. Eight cost 8 × R11 = R88.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.9', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 9, 'G9-NUM-RATIO-RATE', 'A paint mix has red : white = 6 : 3. If the red paint is increased to 12 cups, how much white paint is needed to keep the same mix?', '{"type":"multiple_choice","options":{"A":"18 cups","B":"6 cups","C":"3 cups","D":"12 cups"},"correct_option":"B","distractor_explanations":{"A":"This multiplies by the original red amount rather than the scale factor 2.","C":"This leaves the white amount unchanged while the red amount doubles.","D":"This copies the red amount instead of scaling the white part."}}'::jsonb, 'The red amount doubles from 6 to 12, so the white amount must also double: 3 × 2 = 6 cups.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.10', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 10, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √576?', '{"type":"multiple_choice","options":{"A":"√576 is irrational because it has a root sign.","B":"√576 = −24.","C":"√576 is not real.","D":"√576 = 24, so it is rational."},"correct_option":"D","distractor_explanations":{"A":"The radicand is a perfect square, so its principal root is an integer.","B":"The square-root symbol denotes the principal non-negative root.","C":"The square root of a positive perfect square is real."}}'::jsonb, 'Because 24 × 24 = 576, √576 = 24. Every integer is rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.11', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 11, 'G9-NUM-REAL-IRRATIONAL', 'Which value is √(1/36)?', '{"type":"multiple_choice","options":{"A":"6","B":"−1/6","C":"1/6","D":"1/36"},"correct_option":"C","distractor_explanations":{"A":"This is the denominator rather than the positive fractional root.","B":"The principal square root is non-negative.","D":"This repeats the radicand rather than taking its square root."}}'::jsonb, '(1/6)² = 1/36, so √(1/36) = 1/6. This is rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.12', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 12, 'G9-NUM-FINANCIAL-APPLICATIONS', 'R1400 is invested at 10% compound interest per year. What is the balance after two years?', '{"type":"multiple_choice","options":{"A":"R1704.00","B":"R1694.00","C":"R1680.00","D":"R1540.00"},"correct_option":"B","distractor_explanations":{"A":"This adds an extra R10 after compounding.","C":"This adds simple interest for two years.","D":"This stops after one year."}}'::jsonb, 'After year 1: R1400 × 1.10 = R1540.00. After year 2: R1540.00 × 1.10 = R1694.00.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.13', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 13, 'G9-NUM-WHOLE-HCF-LCM', 'A learner says the HCF of 30 and 36 is their product. Which correction is valid?', '{"type":"multiple_choice","options":{"A":"HCF means the greatest number that divides both; 6 divides both 30 and 36.","B":"HCF means multiply the two numbers and then choose a factor.","C":"HCF is always the smaller of the two numbers.","D":"HCF means the least common multiple of the two numbers."},"correct_option":"A","distractor_explanations":{"B":"The product is not the definition of HCF.","C":"The smaller number need not divide the larger one.","D":"LCM and HCF are different concepts."}}'::jsonb, '30 = 6 × 5 and 36 = 6 × 6. The common greatest factor is 6.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.14', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 14, 'G9-NUM-RATIO-RATE', 'Map set 3 has scale 1 cm : 7 km. Which calculation models 9.5 cm on the map?', '{"type":"multiple_choice","options":{"A":"9.5 ÷ 7 km","B":"9.5 + 7 km","C":"9.5 km","D":"9.5 × 7 = 66.5 km"},"correct_option":"D","distractor_explanations":{"A":"Dividing reverses the scale relationship.","B":"A scale is multiplicative, not additive.","C":"This ignores that 1 cm represents 7 km."}}'::jsonb, 'Each centimetre represents 7 km. Therefore 9.5 cm represents 9.5 × 7 = 66.5 km.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.15', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 15, 'G9-NUM-FINANCIAL-APPLICATIONS', 'Why is compound interest on R1200 at 9% for two years greater than simple interest at the same rate?', '{"type":"multiple_choice","options":{"A":"Interest is subtracted in the first year and added in the second.","B":"The principal is divided by the rate each year.","C":"The second year’s interest is calculated on R1308.00, not on R1200.","D":"The percentage becomes 18% in the second year."},"correct_option":"C","distractor_explanations":{"A":"Both years add interest for a positive investment.","B":"The rate is applied to the growing balance.","D":"The annual rate remains unchanged."}}'::jsonb, 'After year 1 the balance is R1200 × 1.09 = R1308.00. Year 2 interest is calculated from that balance.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.MASTERY-CHALLENGE.16', 'G9-T1-WHOLE-MASTERY-CHALLENGE', 16, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Which situation in set 3 is inverse proportion?', '{"type":"multiple_choice","options":{"A":"A taxi fare rises when more kilometres are travelled at a fixed rate.","B":"For a fixed amount of concrete, more equal-rate mixers finish in fewer hours.","C":"At a fixed unit price, buying more pens increases the total cost.","D":"A recipe doubles every ingredient when the number of portions doubles."},"correct_option":"B","distractor_explanations":{"A":"Distance and fare increase together, so this is direct proportion.","C":"Both quantities increase together, so this is direct proportion.","D":"Both quantities increase together, so this is direct proportion."}}'::jsonb, 'For a fixed total task, rate × time is constant. Increasing the rate or workers therefore decreases the time.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.1', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 1, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √100?', '{"type":"multiple_choice","options":{"A":"10 is a natural number, an integer and a rational number.","B":"It is irrational because it is written with a root sign.","C":"It is not real because square roots are not numbers.","D":"It is the negative integer −10."},"correct_option":"A","distractor_explanations":{"B":"The radicand is a perfect square, so its square root is an integer.","C":"The square root of a positive number is real.","D":"√ denotes the principal, non-negative square root."}}'::jsonb, '√100 = 10. Every natural number is also an integer and rational.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.2', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 2, 'G9-NUM-REAL-IRRATIONAL', 'Which number is irrational in this number set 4?', '{"type":"multiple_choice","options":{"A":"√100","B":"0.125","C":"−3/8","D":"√20"},"correct_option":"D","distractor_explanations":{"A":"√100 is an integer and is therefore rational.","B":"A terminating decimal is rational.","C":"A ratio of integers with a non-zero denominator is rational."}}'::jsonb, '20 is not a perfect square, so √20 cannot be written as a ratio of integers. The other three numbers are rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.3', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 3, 'G9-NUM-WHOLE-HCF-LCM', 'What is the prime factorisation of 480?', '{"type":"multiple_choice","options":{"A":"2^5 × 3² × 5","B":"2^6 × 3 × 5","C":"2^5 × 3 × 5","D":"2^4 × 3 × 5"},"correct_option":"C","distractor_explanations":{"A":"This introduces an extra factor of 3.","B":"This introduces an extra factor of 2.","D":"This omits one factor of 2."}}'::jsonb, '480 = 32 × 15 = 2^5 × 3 × 5.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.4', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 4, 'G9-NUM-WHOLE-HCF-LCM', 'Determine the HCF of 30 and 45.', '{"type":"multiple_choice","options":{"A":"45","B":"15","C":"5","D":"30"},"correct_option":"B","distractor_explanations":{"A":"This is one of the numbers, not a factor of 30.","C":"This is common, but not the highest common factor.","D":"This is one of the numbers, not a factor of 45."}}'::jsonb, '30 = 2 × 3 × 5 and 45 = 3² × 5. The common factors give 3 × 5 = 15.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.5', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 5, 'G9-NUM-WHOLE-HCF-LCM', 'Two bells ring every 20 and 30 minutes. After how many minutes will they next ring together?', '{"type":"multiple_choice","options":{"A":"60","B":"10","C":"50","D":"120"},"correct_option":"A","distractor_explanations":{"B":"This is the HCF, not the first common multiple.","C":"This is not divisible by both intervals.","D":"This doubles the LCM unnecessarily."}}'::jsonb, 'LCM(20, 30) = LCM(2² × 5, 2 × 3 × 5) = 2² × 3 × 5 = 60.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.6', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 6, 'G9-NUM-RATIO-RATE', 'A fruit drink uses 7:3 cups of juice to water. How many cups of water are needed for 14 cups of juice?', '{"type":"multiple_choice","options":{"A":"3","B":"14","C":"21","D":"6"},"correct_option":"D","distractor_explanations":{"A":"This keeps the original water amount instead of scaling it.","B":"This repeats the juice amount as water.","C":"This multiplies the water by the juice amount rather than by the scale factor."}}'::jsonb, 'The juice amount doubles from 7 to 14. Water must also double: 3 × 2 = 6 cups.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.7', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 7, 'G9-NUM-RATIO-RATE', 'A cyclist travels 75 km in 5 hours at a constant speed. What is the unit rate?', '{"type":"multiple_choice","options":{"A":"70 km/h","B":"375 km/h","C":"15 km/h","D":"80 km/h"},"correct_option":"C","distractor_explanations":{"A":"This subtracts rather than finding a unit rate.","B":"This multiplies distance by time instead of dividing.","D":"This adds distance and time instead of dividing."}}'::jsonb, 'Speed = distance ÷ time = 75 ÷ 5 = 15 km/h.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.8', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 8, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Five identical notebooks cost R60. At the same price per notebook, what do eight notebooks cost?', '{"type":"multiple_choice","options":{"A":"R12","B":"R96","C":"R68","D":"R480"},"correct_option":"B","distractor_explanations":{"A":"This is the unit price, not the price of eight notebooks.","C":"This adds the number of notebooks to the price.","D":"This multiplies the total for five notebooks by eight."}}'::jsonb, 'One notebook costs R60 ÷ 5 = R12. Eight cost 8 × R12 = R96.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.9', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 9, 'G9-NUM-RATIO-RATE', 'A paint mix has red : white = 7 : 3. If the red paint is increased to 14 cups, how much white paint is needed to keep the same mix?', '{"type":"multiple_choice","options":{"A":"6 cups","B":"3 cups","C":"14 cups","D":"21 cups"},"correct_option":"A","distractor_explanations":{"B":"This leaves the white amount unchanged while the red amount doubles.","C":"This copies the red amount instead of scaling the white part.","D":"This multiplies by the original red amount rather than the scale factor 2."}}'::jsonb, 'The red amount doubles from 7 to 14, so the white amount must also double: 3 × 2 = 6 cups.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.10', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 10, 'G9-NUM-REAL-IRRATIONAL', 'Which statement correctly classifies √625?', '{"type":"multiple_choice","options":{"A":"√625 = 25, so it is rational.","B":"√625 is irrational because it has a root sign.","C":"√625 = −25.","D":"√625 is not real."},"correct_option":"A","distractor_explanations":{"B":"The radicand is a perfect square, so its principal root is an integer.","C":"The square-root symbol denotes the principal non-negative root.","D":"The square root of a positive perfect square is real."}}'::jsonb, 'Because 25 × 25 = 625, √625 = 25. Every integer is rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.11', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 11, 'G9-NUM-REAL-IRRATIONAL', 'Which value is √(1/49)?', '{"type":"multiple_choice","options":{"A":"1/49","B":"7","C":"−1/7","D":"1/7"},"correct_option":"D","distractor_explanations":{"A":"This repeats the radicand rather than taking its square root.","B":"This is the denominator rather than the positive fractional root.","C":"The principal square root is non-negative."}}'::jsonb, '(1/7)² = 1/49, so √(1/49) = 1/7. This is rational.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.12', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 12, 'G9-NUM-FINANCIAL-APPLICATIONS', 'R1500 is invested at 10% compound interest per year. What is the balance after two years?', '{"type":"multiple_choice","options":{"A":"R1650.00","B":"R1825.00","C":"R1815.00","D":"R1800.00"},"correct_option":"C","distractor_explanations":{"A":"This stops after one year.","B":"This adds an extra R10 after compounding.","D":"This adds simple interest for two years."}}'::jsonb, 'After year 1: R1500 × 1.10 = R1650.00. After year 2: R1650.00 × 1.10 = R1815.00.', 2, 'procedural', 'routine'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.13', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 13, 'G9-NUM-WHOLE-HCF-LCM', 'A learner says the HCF of 36 and 42 is their product. Which correction is valid?', '{"type":"multiple_choice","options":{"A":"HCF means the least common multiple of the two numbers.","B":"HCF means the greatest number that divides both; 6 divides both 36 and 42.","C":"HCF means multiply the two numbers and then choose a factor.","D":"HCF is always the smaller of the two numbers."},"correct_option":"B","distractor_explanations":{"A":"LCM and HCF are different concepts.","C":"The product is not the definition of HCF.","D":"The smaller number need not divide the larger one."}}'::jsonb, '36 = 6 × 6 and 42 = 6 × 7. The common greatest factor is 6.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.14', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 14, 'G9-NUM-RATIO-RATE', 'Map set 4 has scale 1 cm : 8 km. Which calculation models 10.5 cm on the map?', '{"type":"multiple_choice","options":{"A":"10.5 × 8 = 84 km","B":"10.5 ÷ 8 km","C":"10.5 + 8 km","D":"10.5 km"},"correct_option":"A","distractor_explanations":{"B":"Dividing reverses the scale relationship.","C":"A scale is multiplicative, not additive.","D":"This ignores that 1 cm represents 8 km."}}'::jsonb, 'Each centimetre represents 8 km. Therefore 10.5 cm represents 10.5 × 8 = 84 km.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.15', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 15, 'G9-NUM-FINANCIAL-APPLICATIONS', 'Why is compound interest on R1300 at 10% for two years greater than simple interest at the same rate?', '{"type":"multiple_choice","options":{"A":"The percentage becomes 20% in the second year.","B":"Interest is subtracted in the first year and added in the second.","C":"The principal is divided by the rate each year.","D":"The second year’s interest is calculated on R1430.00, not on R1300."},"correct_option":"D","distractor_explanations":{"A":"The annual rate remains unchanged.","B":"Both years add interest for a positive investment.","C":"The rate is applied to the growing balance."}}'::jsonb, 'After year 1 the balance is R1300 × 1.10 = R1430.00. Year 2 interest is calculated from that balance.', 2, 'mathematical_reasoning', 'complex'),
  ('Q.G9.T1C.WHOLE.ENDLINE-REASSESSMENT-B.16', 'G9-T1-WHOLE-MASTERY-ENDLINE-REASSESSMENT-B', 16, 'G9-NUM-DIRECT-INVERSE-PROPORTION', 'Which situation in set 4 is inverse proportion?', '{"type":"multiple_choice","options":{"A":"A recipe doubles every ingredient when the number of portions doubles.","B":"A taxi fare rises when more kilometres are travelled at a fixed rate.","C":"For a fixed data file, a higher download rate needs less time.","D":"At a fixed unit price, buying more pens increases the total cost."},"correct_option":"C","distractor_explanations":{"A":"Both quantities increase together, so this is direct proportion.","B":"Distance and fare increase together, so this is direct proportion.","D":"Both quantities increase together, so this is direct proportion."}}'::jsonb, 'For a fixed total task, rate × time is constant. Increasing the rate or workers therefore decreases the time.', 2, 'mathematical_reasoning', 'complex')
)
insert into public.question_versions(question_item_id,version_number,review_status,activity_type,cognitive_level,representation,difficulty,reasoning_classification,calculator_policy,prompt,answer_config,solution,marks,material_change_note)
select item.id,2,'draft','independent_practice',authored.cognitive_level::public.caps_cognitive_level,'symbolic',authored.difficulty,authored.reasoning_classification,'not_allowed',authored.prompt,authored.answer_config,authored.solution,1,'Sprint 4 closure Whole Numbers blueprint correction: version 2 preserves four independent items for each policy-critical skill; version 1 retained.'
from authored join public.question_items item on item.item_code=authored.item_code
join public.question_versions v1 on v1.question_item_id=item.id and v1.version_number=1
on conflict(question_item_id,version_number) do nothing;

