insert into public.learning_assessment_definition_questions(learning_assessment_definition_id,question_version_id,display_order)
select definition.id,version.id,authored.display_order from authored
join public.learning_assessment_definitions definition on definition.code=authored.definition_code and definition.review_status in ('draft','rejected')
join public.question_items item on item.item_code=authored.item_code
join public.question_versions version on version.question_item_id=item.id and version.version_number=2
on conflict(learning_assessment_definition_id,question_version_id) do update set display_order=excluded.display_order;
